using System.Text.Json;
using System.Text.Json.Nodes;

namespace Tims.Domain.FitEngine;

/// <summary>
/// FIT v2: per-instrument fit against what the vacancy requires. Pure kernels, C#-only (the survival rule: there
/// is no TS twin). Golden-fixtured against contracts/fit-v2-fixtures/*.json, whose expectations were derived by
/// hand from the rules below, not generated by an oracle.
///
/// <para><b>When v2 runs.</b> Only behind <c>Platform:FitEngineV2Enabled</c>, and only for a vacancy whose
/// <c>fit_requirements</c> carries an <c>assessments</c> ARRAY. Without that key the v1 path runs unchanged, so
/// turning the flag on changes no vacancy until HR configures one.</para>
///
/// <para><b>Per-instrument fit (0..100).</b>
/// lia — meet-or-exceed on the global percentile: <c>min(100, round(p / min × 100))</c>, 100 when min ≤ 0 (the
/// experience curve). english — the CEFR ladder A1..C2: 100 at or above the requirement, else
/// <c>round((achieved + 1) / 6 × 100)</c> (the education ladder). itcia — the 1..5 level ladder: 100 at or above
/// the requirement, else <c>round(level / 5 × 100)</c>. native_quiz — the normalized score as stored (v1
/// semantics), or the meet-or-exceed curve when the vacancy sets <c>min.score</c>. Personality, MI and PCA are
/// advisory only and never get a score. <c>round</c> is <see cref="FitEngineKernels.JsRound"/>.</para>
///
/// <para><b>Gates</b> evaluate the same minimum: met / not_met, or unknown when there is no usable result. A gate
/// never feeds the score and never rejects or zeroes a candidate.</para>
///
/// <para><b>Integrity.</b> A result marked <see cref="ResultIntegrity.NeedsReview"/> (voided, flagged, awaiting
/// review) shows as <c>needs_review</c>, its gate as unknown, and is excluded from the <c>assessment</c>
/// dimension: it is never read as a low instrument score. Excluding it still moves the OVERALL number (the
/// remaining dimensions are renormalized exactly as for a candidate with no result, and when nothing else is
/// available the overall is v1's 0/partial no-data value), so a scored result awaiting review sets
/// <see cref="FitV2Evaluation.ReviewPending"/>: the row is stored as partial and the breakdown carries
/// <c>reviewPending: true</c> for readers to hold it apart. Only the most recent result per instrument is
/// considered (completedAt DESC, nulls last, then resultId ordinal ascending); an older valid attempt does not
/// stand in for a newer one under review.</para>
///
/// <para><b>Weighting rule.</b> The <c>assessment</c> dimension is the weighted mean of the scored instruments
/// that have a score, rounded with JsRound. The weights are the declared <c>weight</c>s when EVERY scored entry
/// declares a valid one (a JSON number in (0, 100]); otherwise every scored instrument weighs the same. This is
/// exactly "split the role-family profile's assessment weight across the scored instruments by their weights":
/// instrument i carries <c>profile.assessment × wᵢ / Σ w</c> over the instruments with a score. When none has a
/// score the dimension is null and the five-dimension renormalization removes it, as v1 does for any missing
/// dimension. Gate and advisory entries weigh nothing. <c>isPartial</c> keeps its v1 meaning (one of the five
/// dimensions is null), and is also set when <see cref="FitV2Evaluation.ReviewPending"/> is (simulateWeights
/// recomputes it from the five dimension keys only, so for such a row it can report false).</para>
///
/// <para><b>English and the languages dimension.</b> When a SCORED english entry has a valid CEFR result, that
/// result decides whether "English" counts as covered among <c>requiredLanguages</c> (achieved ≥ the entry's
/// minimum), overriding the CV self-report for English only. Other languages still come from the CV. If the CV
/// lists no languages and the vacancy also requires a non-English language, the dimension stays null as in v1 (a
/// parser gap is not a missing language); if English is the only required language, the test alone decides. A
/// GATE english entry never touches any dimension — not even languages — so a not-met gate cannot lower the
/// overall score; HR sees its met/not_met next to the CV self-report (<c>languagesEvidence</c> = <c>cv</c>).</para>
///
/// <para><b>Visibility.</b> The breakdown is readable by every fit_engine reader (leader@team included), so an
/// entry carries the derived fit, the gate state, the requirement and the result id, never the raw result
/// (percentile, CEFR, level) nor the internal <c>model_version</c>. Advisory entries carry status only.</para>
/// </summary>
public static class FitV2Kernels
{
    /// <summary>The <c>fitVersion</c> written into a v2 breakdown.</summary>
    public const int FitVersion = 2;

    /// <summary>Only the first entries of <c>assessments[]</c> are read; at most 7 survive de-duplication anyway.</summary>
    public const int MaxRequirementEntries = 32;

    /// <summary>A longer (or empty) reason is dropped, not truncated.</summary>
    public const int MaxReasonLength = 500;

    /// <summary>The largest declared weight accepted (weights are relative; this only keeps the math finite).</summary>
    public const double MaxWeight = 100;

    /// <summary>The CEFR ladder, lowest → highest. The index is the ordinal.</summary>
    public static readonly IReadOnlyList<string> CefrLevels = ["A1", "A2", "B1", "B2", "C1", "C2"];

    /// <summary>ITC-IA levels run 1..5.</summary>
    public const int ItciaMaxLevel = 5;

    private static readonly HashSet<string> EnglishNames = new(StringComparer.Ordinal) { "english", "inglés", "ingles" };

    // ───────────────────────────── requirements ─────────────────────────────

    /// <summary>
    /// <c>fit_requirements.assessments[]</c>, parsed leniently. Returns null when the jsonb is not an object or has
    /// no <c>assessments</c> array (the v1 path then runs). Otherwise returns the valid entries in order; a bad
    /// entry is dropped, never an error:
    /// <list type="bullet">
    /// <item>not an object, or <c>instrument</c> not one of <see cref="FitInstruments.All"/> (trimmed,
    /// case-insensitive) → dropped;</item>
    /// <item><c>use</c> absent or null → the instrument default (lia/itcia/native_quiz scored, english gate,
    /// personality/mi/pca advisory); present but not scored|gate|advisory → dropped; personality/mi/pca are
    /// coerced to advisory whatever was configured;</item>
    /// <item>lia/english/itcia used as scored or gate need a valid <c>min</c> (globalPercentile 0..100 / cefr
    /// A1..C2 / integer level 1..5), else dropped; native_quiz used as a gate needs <c>min.score</c> 0..100, as
    /// scored it is optional; advisory entries keep no minimum;</item>
    /// <item><c>weight</c> is kept only on scored entries and only as a JSON number in (0, 100];
    /// <c>reason</c> only as a string of 1..500 characters after trimming;</item>
    /// <item>a second entry for an instrument already kept is dropped (the first valid entry wins).</item>
    /// </list>
    /// </summary>
    public static IReadOnlyList<AssessmentRequirement>? ParseAssessmentRequirements(JsonNode? fitRequirements)
    {
        if (fitRequirements is not JsonObject obj
            || !obj.TryGetPropertyValue("assessments", out var node)
            || node is not JsonArray entries)
        {
            return null;
        }

        var parsed = new List<AssessmentRequirement>();
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var entry in entries.Take(MaxRequirementEntries))
        {
            if (TryParseRequirement(entry) is { } requirement && seen.Add(requirement.Instrument))
            {
                parsed.Add(requirement);
            }
        }

        return parsed;
    }

    private static AssessmentRequirement? TryParseRequirement(JsonNode? entry)
    {
        if (entry is not JsonObject e || !TryGetString(e, "instrument", out var rawInstrument))
        {
            return null;
        }

        var instrument = rawInstrument.Trim().ToLowerInvariant();
        if (!FitInstruments.All.Contains(instrument))
        {
            return null;
        }

        string use;
        if (e.TryGetPropertyValue("use", out var useNode) && useNode is not null)
        {
            if (useNode is not JsonValue useValue || !useValue.TryGetValue<string>(out var rawUse))
            {
                return null;
            }

            use = rawUse.Trim().ToLowerInvariant();
            if (use is not (FitInstrumentUses.Scored or FitInstrumentUses.Gate or FitInstrumentUses.Advisory))
            {
                return null;
            }
        }
        else
        {
            use = DefaultUse(instrument);
        }

        if (FitInstruments.IsAdvisoryOnly(instrument))
        {
            use = FitInstrumentUses.Advisory;
        }

        InstrumentMinimum? min = null;
        if (use != FitInstrumentUses.Advisory)
        {
            min = ParseMinimum(instrument, e.TryGetPropertyValue("min", out var minNode) ? minNode : null);
            var minRequired = instrument != FitInstruments.NativeQuiz || use == FitInstrumentUses.Gate;
            if (min is null && minRequired)
            {
                return null;
            }
        }

        double? weight = null;
        if (use == FitInstrumentUses.Scored
            && e.TryGetPropertyValue("weight", out var weightNode)
            && weightNode is JsonValue weightValue
            && TryGetFiniteNumber(weightValue, out var w)
            && w > 0
            && w <= MaxWeight)
        {
            weight = w;
        }

        string? reason = null;
        if (TryGetString(e, "reason", out var rawReason))
        {
            var trimmed = rawReason.Trim();
            if (trimmed.Length is > 0 and <= MaxReasonLength)
            {
                reason = trimmed;
            }
        }

        return new AssessmentRequirement(instrument, use, min, weight, reason);
    }

    private static string DefaultUse(string instrument) => instrument switch
    {
        FitInstruments.English => FitInstrumentUses.Gate,
        FitInstruments.Lia or FitInstruments.Itcia or FitInstruments.NativeQuiz => FitInstrumentUses.Scored,
        _ => FitInstrumentUses.Advisory,
    };

    private static InstrumentMinimum? ParseMinimum(string instrument, JsonNode? node)
    {
        if (node is not JsonObject min)
        {
            return null;
        }

        switch (instrument)
        {
            case FitInstruments.Lia:
                return min.TryGetPropertyValue("globalPercentile", out var p) && p is JsonValue pv
                    && TryGetFiniteNumber(pv, out var percentile) && percentile is >= 0 and <= 100
                    ? new InstrumentMinimum(percentile, null, null, null)
                    : null;
            case FitInstruments.English:
                return TryGetString(min, "cefr", out var rawCefr) && NormalizeCefr(rawCefr) is { } cefr
                    ? new InstrumentMinimum(null, cefr, null, null)
                    : null;
            case FitInstruments.Itcia:
                return min.TryGetPropertyValue("level", out var l) && l is JsonValue lv
                    && TryGetFiniteNumber(lv, out var level) && level == Math.Floor(level)
                    && level is >= 1 and <= ItciaMaxLevel
                    ? new InstrumentMinimum(null, null, (int)level, null)
                    : null;
            case FitInstruments.NativeQuiz:
                return min.TryGetPropertyValue("score", out var s) && s is JsonValue sv
                    && TryGetFiniteNumber(sv, out var score) && score is >= 0 and <= 100
                    ? new InstrumentMinimum(null, null, null, score)
                    : null;
            default:
                return null;
        }
    }

    // ───────────────────────────── per-instrument kernels ─────────────────────────────

    /// <summary>
    /// The meet-or-exceed curve (TS <c>deriveExperienceScore</c>'s shape): <c>min(100, round(value / minimum ×
    /// 100))</c>, and 100 when the minimum is ≤ 0. Used by lia (global percentile) and by native_quiz with a
    /// <c>min.score</c>.
    /// </summary>
    public static double MeetOrExceed(double value, double minimum) =>
        minimum <= 0 ? 100 : Math.Min(100, FitEngineKernels.JsRound(value / minimum * 100));

    /// <summary>The CEFR ladder: 100 at or above the requirement, else <c>round((achieved + 1) / 6 × 100)</c>.</summary>
    public static double CefrLadder(int achievedOrdinal, int requiredOrdinal) =>
        achievedOrdinal >= requiredOrdinal
            ? 100
            : FitEngineKernels.JsRound((achievedOrdinal + 1) / (double)CefrLevels.Count * 100);

    /// <summary>The ITC-IA level ladder: 100 at or above the requirement, else <c>round(level / 5 × 100)</c>.</summary>
    public static double ItciaLadder(int level, int requiredLevel) =>
        level >= requiredLevel ? 100 : FitEngineKernels.JsRound(level / (double)ItciaMaxLevel * 100);

    /// <summary>A CEFR label → its ordinal (A1 = 0 … C2 = 5), trimmed and case-insensitive; null when unknown.</summary>
    public static int? CefrOrdinal(string? cefr)
    {
        if (cefr is null || NormalizeCefr(cefr) is not { } normalized)
        {
            return null;
        }

        for (var i = 0; i < CefrLevels.Count; i++)
        {
            if (CefrLevels[i] == normalized)
            {
                return i;
            }
        }

        return null;
    }

    /// <summary>True when a (normalized, lower-cased) language label names English ("english", "inglés", "ingles").</summary>
    public static bool IsEnglish(string language) =>
        EnglishNames.Contains(FitEngineKernels.NormalizeLanguage(language).ToLowerInvariant());

    // ───────────────────────────── evaluation ─────────────────────────────

    /// <summary>
    /// Evaluate the configured instruments against the candidate's results. Results for instruments the vacancy
    /// does not list are ignored (job-relatedness: only listed instruments count). Entries keep the
    /// requirements' order. See the class summary for every rule applied here.
    /// </summary>
    public static FitV2Evaluation Evaluate(
        IReadOnlyList<AssessmentRequirement> requirements,
        IReadOnlyList<InstrumentResult> results,
        IReadOnlyDictionary<string, double> profileWeights,
        FitRequirements fitRequirements,
        JsonNode? candidateLanguages)
    {
        var assessmentWeight = profileWeights.TryGetValue("assessment", out var aw) ? aw : 0d;
        var latest = SelectLatestPerInstrument(results);

        var scored = requirements.Where(r => r.Use == FitInstrumentUses.Scored).ToList();
        var useDeclaredWeights = scored.Count > 0 && scored.All(r => r.Weight is not null);

        var drafts = new List<Draft>(requirements.Count);
        foreach (var requirement in requirements)
        {
            latest.TryGetValue(requirement.Instrument, out var result);
            drafts.Add(Assess(requirement, result));
        }

        // The assessment dimension: weighted mean over scored entries that HAVE a score.
        var weightSum = 0d;
        var weighted = 0d;
        foreach (var draft in drafts)
        {
            if (draft.Requirement.Use == FitInstrumentUses.Scored && draft.Score is { } score)
            {
                var w = RelativeWeight(draft.Requirement, useDeclaredWeights);
                weightSum += w;
                weighted += score * w;
            }
        }

        double? assessment = weightSum > 0 ? FitEngineKernels.JsRound(weighted / weightSum) : null;

        // A scored result awaiting review is left out above; the overall number is then provisional.
        var reviewPending = drafts.Any(d =>
            d.Requirement.Use == FitInstrumentUses.Scored && d.Status == FitInstrumentStatuses.NeedsReview);

        // English → languages: only a SCORED english entry may move a number (a gate never does).
        bool? englishCovered = null;
        var englishDraft = drafts.FirstOrDefault(d => d.Requirement.Instrument == FitInstruments.English);
        if (englishDraft is not null
            && englishDraft.Requirement.Use == FitInstrumentUses.Scored
            && englishDraft.Status == FitInstrumentStatuses.Completed
            && CefrOrdinal(englishDraft.Result!.Cefr) is { } achieved
            && CefrOrdinal(englishDraft.Requirement.Min?.Cefr) is { } required)
        {
            englishCovered = achieved >= required;
        }

        var (languages, usedAssessment) = DeriveLanguageScoreV2(candidateLanguages, fitRequirements, englishCovered);
        var englishRequired = fitRequirements.RequiredLanguages?.Any(IsEnglish) == true;

        var entries = new List<InstrumentFitEntry>(drafts.Count);
        foreach (var draft in drafts)
        {
            var requirement = draft.Requirement;
            double? share = null;
            double? effective = null;
            double? appliedWeight = null;
            if (requirement.Use == FitInstrumentUses.Scored)
            {
                appliedWeight = useDeclaredWeights ? requirement.Weight : null;
                if (draft.Score is not null && weightSum > 0)
                {
                    var exact = RelativeWeight(requirement, useDeclaredWeights) / weightSum;
                    share = Round4(exact);
                    effective = Round4(exact * assessmentWeight);
                }
            }

            string? languagesEvidence = null;
            if (requirement.Instrument == FitInstruments.English && englishRequired)
            {
                languagesEvidence = usedAssessment ? "assessment" : "cv";
            }

            entries.Add(new InstrumentFitEntry(
                requirement.Instrument,
                requirement.Use,
                draft.Status,
                draft.Score,
                draft.Gate,
                appliedWeight,
                share,
                effective,
                requirement.Min,
                requirement.Reason,
                draft.Result?.ResultId,
                draft.Result?.Source,
                draft.Result?.ContentVersion,
                draft.Result?.NormVersion,
                languagesEvidence));
        }

        return new FitV2Evaluation(assessment, languages, entries, reviewPending);
    }

    /// <summary>
    /// The v1 <see cref="FitEngineKernels.DeriveLanguageScore"/> with English decided by the test when
    /// <paramref name="englishCovered"/> is set. Returns the score and whether the test result was used.
    /// <paramref name="englishCovered"/> null → exactly v1. No English among <c>requiredLanguages</c> → exactly v1.
    /// CV languages absent or empty → the test alone decides when English is the only required language, else
    /// null (v1). Otherwise: proportion of required languages covered, English by the test and the rest by the
    /// CV, rounded with JsRound.
    /// </summary>
    public static (double? Score, bool UsedAssessment) DeriveLanguageScoreV2(
        JsonNode? languages, FitRequirements requirements, bool? englishCovered)
    {
        var v1 = FitEngineKernels.DeriveLanguageScore(languages, requirements);
        if (englishCovered is not { } covered
            || requirements.RequiredLanguages is not { Count: > 0 } required
            || !required.Any(IsEnglish))
        {
            return (v1, false);
        }

        if (languages is not JsonArray spoken || spoken.Count == 0)
        {
            return required.All(IsEnglish) ? (covered ? 100 : 0, true) : (v1, false);
        }

        var candidateSet = new HashSet<string>(StringComparer.Ordinal);
        foreach (var entry in spoken)
        {
            if (entry is JsonValue value && value.TryGetValue<string>(out var language))
            {
                candidateSet.Add(FitEngineKernels.NormalizeLanguage(language).ToLowerInvariant());
            }
        }

        var matched = required.Count(l =>
            IsEnglish(l) ? covered : candidateSet.Contains(FitEngineKernels.NormalizeLanguage(l).ToLowerInvariant()));
        return (FitEngineKernels.JsRound(matched / (double)required.Count * 100), true);
    }

    // ───────────────────────────── breakdown JSON ─────────────────────────────

    /// <summary>
    /// The v2 breakdown: the v1 keys first, in the v1 order (<c>assessment, interview, experience, education,
    /// languages, llmJudgment</c>, so every v1 reader — simulateWeights, the web panels, the AI explainer — keeps
    /// working), then <c>fitVersion</c>, <c>reviewPending</c> (see <see cref="FitV2Evaluation.ReviewPending"/>) and
    /// <c>assessments</c> (one entry per configured instrument).
    /// </summary>
    public static JsonObject BuildBreakdown(
        IReadOnlyDictionary<string, double?> rawScores, IReadOnlyList<InstrumentFitEntry> entries, bool reviewPending)
    {
        var breakdown = new JsonObject();
        foreach (var dim in FitEngineKernels.FitDimensions)
        {
            breakdown[dim] = rawScores.TryGetValue(dim, out var value) && value is { } score
                ? JsonValue.Create(score)
                : null;
        }

        breakdown["llmJudgment"] = null;
        breakdown["fitVersion"] = FitVersion;
        breakdown["reviewPending"] = reviewPending;
        var array = new JsonArray();
        foreach (var entry in entries)
        {
            array.Add(EntryToJson(entry));
        }

        breakdown["assessments"] = array;
        return breakdown;
    }

    /// <summary>One entry as stored: every key always present, nulls explicit.</summary>
    public static JsonObject EntryToJson(InstrumentFitEntry entry) => new()
    {
        ["instrument"] = entry.Instrument,
        ["use"] = entry.Use,
        ["status"] = entry.Status,
        ["score"] = Number(entry.Score),
        ["gate"] = entry.Gate,
        ["weight"] = Number(entry.Weight),
        ["assessmentShare"] = Number(entry.AssessmentShare),
        ["effectiveWeight"] = Number(entry.EffectiveWeight),
        ["min"] = MinimumToJson(entry.Min),
        ["reason"] = entry.Reason,
        ["resultId"] = entry.ResultId,
        ["source"] = entry.Source,
        ["contentVersion"] = entry.ContentVersion,
        ["normVersion"] = entry.NormVersion,
        ["languagesEvidence"] = entry.LanguagesEvidence,
    };

    /// <summary>The minimum as stored: only the field that is set (<c>{"cefr":"B2"}</c>), or null.</summary>
    public static JsonObject? MinimumToJson(InstrumentMinimum? min)
    {
        if (min is null)
        {
            return null;
        }

        var json = new JsonObject();
        if (min.GlobalPercentile is { } percentile)
        {
            json["globalPercentile"] = percentile;
        }

        if (min.Cefr is { } cefr)
        {
            json["cefr"] = cefr;
        }

        if (min.Level is { } level)
        {
            json["level"] = level;
        }

        if (min.Score is { } score)
        {
            json["score"] = score;
        }

        return json;
    }

    // ───────────────────────────── helpers ─────────────────────────────

    private sealed record Draft(
        AssessmentRequirement Requirement, InstrumentResult? Result, string Status, double? Score, string? Gate);

    private static Draft Assess(AssessmentRequirement requirement, InstrumentResult? result)
    {
        string status;
        if (result is null)
        {
            status = FitInstrumentStatuses.NoResult;
        }
        else if (result.Integrity == ResultIntegrity.NeedsReview)
        {
            status = FitInstrumentStatuses.NeedsReview;
        }
        else if (requirement.Use != FitInstrumentUses.Advisory && !HasUsableValue(requirement.Instrument, result))
        {
            status = FitInstrumentStatuses.NoValue;
        }
        else
        {
            status = FitInstrumentStatuses.Completed;
        }

        var completed = status == FitInstrumentStatuses.Completed;
        double? score = null;
        string? gate = null;
        switch (requirement.Use)
        {
            case FitInstrumentUses.Scored:
                score = completed ? Fit(requirement, result!) : null;
                break;
            case FitInstrumentUses.Gate:
                gate = !completed
                    ? FitGateStates.Unknown
                    : Meets(requirement, result!) ? FitGateStates.Met : FitGateStates.NotMet;
                break;
        }

        return new Draft(requirement, result, status, score, gate);
    }

    private static bool HasUsableValue(string instrument, InstrumentResult result) => instrument switch
    {
        FitInstruments.Lia => result.GlobalPercentile is { } p && double.IsFinite(p) && p is >= 0 and <= 100,
        FitInstruments.English => CefrOrdinal(result.Cefr) is not null,
        FitInstruments.Itcia => result.Level is >= 1 and <= ItciaMaxLevel,
        FitInstruments.NativeQuiz => result.NormalizedScore is { } s && double.IsFinite(s),
        _ => false,
    };

    // Only called for a scored entry whose result is Completed (so the value is present and valid).
    private static double Fit(AssessmentRequirement requirement, InstrumentResult result) =>
        requirement.Instrument switch
        {
            FitInstruments.Lia => MeetOrExceed(result.GlobalPercentile!.Value, requirement.Min!.GlobalPercentile!.Value),
            FitInstruments.English => CefrLadder(CefrOrdinal(result.Cefr)!.Value, CefrOrdinal(requirement.Min!.Cefr)!.Value),
            FitInstruments.Itcia => ItciaLadder(result.Level!.Value, requirement.Min!.Level!.Value),
            FitInstruments.NativeQuiz => requirement.Min?.Score is { } minScore
                ? MeetOrExceed(result.NormalizedScore!.Value, minScore)
                : result.NormalizedScore!.Value,
            _ => throw new InvalidOperationException($"instrument {requirement.Instrument} is never scored"),
        };

    // Only called for a gate entry whose result is Completed. Every gate entry carries a minimum (the parse
    // drops a gate without one).
    private static bool Meets(AssessmentRequirement requirement, InstrumentResult result) =>
        requirement.Instrument switch
        {
            FitInstruments.Lia => result.GlobalPercentile!.Value >= requirement.Min!.GlobalPercentile!.Value,
            FitInstruments.English => CefrOrdinal(result.Cefr)!.Value >= CefrOrdinal(requirement.Min!.Cefr)!.Value,
            FitInstruments.Itcia => result.Level!.Value >= requirement.Min!.Level!.Value,
            FitInstruments.NativeQuiz => result.NormalizedScore!.Value >= requirement.Min!.Score!.Value,
            _ => throw new InvalidOperationException($"instrument {requirement.Instrument} is never a gate"),
        };

    private static double RelativeWeight(AssessmentRequirement requirement, bool useDeclaredWeights) =>
        useDeclaredWeights ? requirement.Weight!.Value : 1d;

    private static Dictionary<string, InstrumentResult> SelectLatestPerInstrument(
        IReadOnlyList<InstrumentResult> results)
    {
        var latest = new Dictionary<string, InstrumentResult>(StringComparer.Ordinal);
        foreach (var group in results.GroupBy(r => r.Instrument, StringComparer.Ordinal))
        {
            latest[group.Key] = group
                .OrderBy(r => r.CompletedAt is null ? 1 : 0)
                .ThenByDescending(r => r.CompletedAt)
                .ThenBy(r => r.ResultId, StringComparer.Ordinal)
                .First();
        }

        return latest;
    }

    private static string? NormalizeCefr(string raw)
    {
        var upper = raw.Trim().ToUpperInvariant();
        return CefrLevels.Contains(upper) ? upper : null;
    }

    private static double Round4(double value) => Math.Round(value, 4, MidpointRounding.AwayFromZero);

    private static JsonNode? Number(double? value) => value is { } v ? JsonValue.Create(v) : null;

    private static bool TryGetString(JsonObject obj, string key, out string value)
    {
        if (obj.TryGetPropertyValue(key, out var node) && node is JsonValue v && v.TryGetValue<string>(out var s))
        {
            value = s;
            return true;
        }

        value = string.Empty;
        return false;
    }

    // A JSON-number-kind value that is finite (a string "5", a bool, NaN or ±∞ must NOT parse).
    private static bool TryGetFiniteNumber(JsonValue value, out double number)
    {
        if (value.GetValueKind() == JsonValueKind.Number)
        {
            number = value.GetValue<double>();
            return double.IsFinite(number);
        }

        number = 0;
        return false;
    }
}
